RESET ROLE;
SELECT public.test_assert((SELECT status='scheduled' FROM public.matches WHERE event_id='auto'),'invalid batch rolls back earlier match');
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM public.external_match_imports),'invalid batch leaves no import');
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM yoso_approval_private.revisions WHERE event_id='auto'),'invalid batch rolls back revision creation');
SET LOCAL ROLE service_role;
SELECT public.test_assert((public.auto_apply_koshien_official_results('auto','[{"roundKey":"R1","matchNo":1,"matchId":"40000000-0000-0000-0000-000000000001","team1Id":"30000000-0000-0000-0000-000000000001","team2Id":"30000000-0000-0000-0000-000000000002","team1Score":3,"team2Score":1,"winnerTeamId":"30000000-0000-0000-0000-000000000001","loserTeamId":"30000000-0000-0000-0000-000000000002","externalKey":"jhbf:summer:2026:2026-08-01:1","sourceUrl":"https://www.jhbf.or.jp/sensyuken/2026/schedule/schedule_20260801.html","normalizedPayload":{"roundKey":"R1","matchNo":1,"matchId":"40000000-0000-0000-0000-000000000001","team1Id":"30000000-0000-0000-0000-000000000001","team2Id":"30000000-0000-0000-0000-000000000002","team1Score":3,"team2Score":1,"winnerTeamId":"30000000-0000-0000-0000-000000000001","loserTeamId":"30000000-0000-0000-0000-000000000002","externalKey":"jhbf:summer:2026:2026-08-01:1","sourceUrl":"https://www.jhbf.or.jp/sensyuken/2026/schedule/schedule_20260801.html","source":"jhbf"}}]')->>'changed')::int=1,'service applies official result');
RESET ROLE;
SELECT public.test_assert((SELECT revision=1 FROM yoso_approval_private.revisions WHERE event_id='auto'),'applied result increments once');
SELECT public.test_assert((SELECT team1_score=3 AND status='completed' FROM public.matches WHERE event_id='auto'),'official score persisted');
SELECT public.test_assert((SELECT payload->'matches'->0->>'status'='completed' FROM public.results WHERE event_id='auto'),'official slot persisted');
SET LOCAL ROLE service_role;
SELECT public.test_assert((public.auto_apply_koshien_official_results('auto','[{"roundKey":"R1","matchNo":1,"matchId":"40000000-0000-0000-0000-000000000001","team1Id":"30000000-0000-0000-0000-000000000001","team2Id":"30000000-0000-0000-0000-000000000002","team1Score":3,"team2Score":1,"winnerTeamId":"30000000-0000-0000-0000-000000000001","loserTeamId":"30000000-0000-0000-0000-000000000002","externalKey":"jhbf:summer:2026:2026-08-01:1","sourceUrl":"https://www.jhbf.or.jp/sensyuken/2026/schedule/schedule_20260801.html","normalizedPayload":{"roundKey":"R1","matchNo":1,"matchId":"40000000-0000-0000-0000-000000000001","team1Id":"30000000-0000-0000-0000-000000000001","team2Id":"30000000-0000-0000-0000-000000000002","team1Score":3,"team2Score":1,"winnerTeamId":"30000000-0000-0000-0000-000000000001","loserTeamId":"30000000-0000-0000-0000-000000000002","externalKey":"jhbf:summer:2026:2026-08-01:1","sourceUrl":"https://www.jhbf.or.jp/sensyuken/2026/schedule/schedule_20260801.html","source":"jhbf"}}]')->>'skipped')::int=1,'repeat official result skipped');
RESET ROLE;
SELECT public.test_assert((SELECT revision=1 FROM yoso_approval_private.revisions WHERE event_id='auto'),'repeat does not invalidate approval');
UPDATE public.external_match_imports SET status='canceled' WHERE event_id='auto';
SET LOCAL ROLE service_role;
SELECT public.test_assert((public.auto_apply_koshien_official_results('auto','[{"roundKey":"R1","matchNo":1,"matchId":"40000000-0000-0000-0000-000000000001","team1Id":"30000000-0000-0000-0000-000000000001","team2Id":"30000000-0000-0000-0000-000000000002","team1Score":3,"team2Score":1,"winnerTeamId":"30000000-0000-0000-0000-000000000001","loserTeamId":"30000000-0000-0000-0000-000000000002","externalKey":"jhbf:summer:2026:2026-08-01:1","sourceUrl":"https://www.jhbf.or.jp/sensyuken/2026/schedule/schedule_20260801.html","normalizedPayload":{"roundKey":"R1","matchNo":1,"matchId":"40000000-0000-0000-0000-000000000001","team1Id":"30000000-0000-0000-0000-000000000001","team2Id":"30000000-0000-0000-0000-000000000002","team1Score":3,"team2Score":1,"winnerTeamId":"30000000-0000-0000-0000-000000000001","loserTeamId":"30000000-0000-0000-0000-000000000002","externalKey":"jhbf:summer:2026:2026-08-01:1","sourceUrl":"https://www.jhbf.or.jp/sensyuken/2026/schedule/schedule_20260801.html","source":"jhbf"}}]')->>'blocked')::int=1,'canceled import blocked');
RESET ROLE;
SELECT public.test_assert((SELECT revision=1 FROM yoso_approval_private.revisions WHERE event_id='auto'),'blocked import does not invalidate approval');
ROLLBACK;
